'use client';

import { useState, useEffect, useCallback } from 'react';
import { Users, Search, Phone, MapPin, UserCircle, History, ExternalLink, Loader2, Plus, AlertCircle, UserPlus } from 'lucide-react';
import { getCustomersList, createCustomer } from '@/app/actions/customers';
import Link from 'next/link';
import clsx from 'clsx';

interface CustomerGroup {
    name: string;
}

interface Customer {
    id: string;
    name: string;
    phone: string | null;
    address: string | null;
    balance: number | string;
    type: string;
    group?: CustomerGroup | null;
}

export default function CustomersPage() {
    const [customers, setCustomers] = useState<Customer[]>([]);
    const [search, setSearch] = useState('');
    const [loading, setLoading] = useState(true);

    // Add Customer Modal
    const [showAddModal, setShowAddModal] = useState(false);
    const [newCustomer, setNewCustomer] = useState({ name: '', phone: '', address: '' });
    const [creating, setCreating] = useState(false);
    const [formError, setFormError] = useState<string | null>(null);

    const loadCustomers = useCallback(async (showLoading = false) => {
        if (showLoading) setLoading(true);
        const data = await getCustomersList();
        setCustomers(data);
        setLoading(false);
    }, []);

    useEffect(() => {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        loadCustomers(false);
    }, [loadCustomers]);

    const handleCreateCustomer = async () => {
        if (!newCustomer.name.trim()) {
            setFormError('Customer name is required.');
            return;
        }
        setCreating(true);
        setFormError(null);

        const result = await createCustomer({
            name: newCustomer.name,
            phone: newCustomer.phone || undefined,
            address: newCustomer.address || undefined,
        });

        if (result.success) {
            setShowAddModal(false);
            setNewCustomer({ name: '', phone: '', address: '' });
            loadCustomers(true);
        } else {
            setFormError(result.error || 'Failed to create customer.');
        }
        setCreating(false);
    };

    const handleSearchChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setSearch(e.target.value), []);
    const handleOpenAddModal = useCallback(() => setShowAddModal(true), []);
    const handleCloseAddModal = useCallback(() => {
        setShowAddModal(false);
        setFormError(null);
        setNewCustomer({ name: '', phone: '', address: '' });
    }, []);
    const handleNewCustomerNameChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setNewCustomer(prev => ({ ...prev, name: e.target.value })), []);
    const handleNewCustomerPhoneChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setNewCustomer(prev => ({ ...prev, phone: e.target.value })), []);
    const handleNewCustomerAddressChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setNewCustomer(prev => ({ ...prev, address: e.target.value })), []);

    const filtered = customers.filter(c =>
        c.name.toLowerCase().includes(search.toLowerCase()) ||
        (c.phone && c.phone.includes(search))
    );

    const totalDebt = customers.reduce((sum, c) => sum + (Number(c.balance) > 0 ? Number(c.balance) : 0), 0);

    return (
        <div className="space-y-6 max-w-7xl mx-auto">
            {/* Header */}
            <div className="flex flex-col md:flex-row justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-black tracking-tight text-foreground flex items-center gap-3">
                        <Users size={32} className="text-primary" />
                        العملاء <span className="text-muted-foreground font-normal">/ Customers</span>
                    </h2>
                    <p className="text-muted-foreground mt-1 text-lg">Manage and analyze your customer base</p>
                </div>

                <div className="flex items-center gap-3">
                    <div className="relative group flex-1 md:w-80">
                        <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground group-focus-within:text-primary transition-colors" size={20} />
                        <input
                            type="text"
                            placeholder="Search by name or phone..."
                            value={search}
                            onChange={handleSearchChange}
                            className="w-full pl-10 pr-4 py-3 bg-card border border-border rounded-xl focus:ring-2 focus:ring-primary/20 outline-none transition-all shadow-sm"
                        />
                    </div>
                    <button
                        onClick={handleOpenAddModal}
                        className="flex items-center gap-2 px-5 py-3 bg-primary text-primary-foreground rounded-xl font-bold text-sm hover:bg-primary/90 hover:shadow-lg hover:shadow-primary/20 transition-all shadow-md whitespace-nowrap"
                    >
                        <UserPlus size={18} />
                        Add Customer
                    </button>
                </div>
            </div>

            {/* Stats Bar */}
            <div className="grid grid-cols-2 md:grid-cols-3 gap-4">
                <div className="bg-card border border-border rounded-2xl p-4">
                    <div className="text-sm text-muted-foreground font-medium">Total Customers</div>
                    <div className="text-2xl font-black mt-1">{customers.length}</div>
                </div>
                <div className="bg-card border border-border rounded-2xl p-4">
                    <div className="text-sm text-muted-foreground font-medium">With Outstanding Debt</div>
                    <div className="text-2xl font-black text-red-600 mt-1">{customers.filter(c => Number(c.balance) > 0).length}</div>
                </div>
                <div className="bg-card border border-border rounded-2xl p-4 col-span-2 md:col-span-1">
                    <div className="text-sm text-muted-foreground font-medium">Total Owed</div>
                    <div className="text-2xl font-black text-red-600 mt-1">EGP {totalDebt.toLocaleString()}</div>
                </div>
            </div>

            {/* Customer Grid */}
            {loading ? (
                <div className="flex flex-col items-center justify-center h-64 gap-4">
                    <Loader2 className="animate-spin text-primary" size={48} />
                    <p className="text-muted-foreground font-medium animate-pulse">Fetching customer intelligence...</p>
                </div>
            ) : (
                <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
                    {filtered.map((customer, idx) => (
                        <div key={idx} className="bg-card border border-border rounded-2xl p-5 hover:border-primary/50 transition-all hover:shadow-lg group flex flex-col relative overflow-hidden">
                            <div className="absolute top-0 right-0 p-3 opacity-10 group-hover:opacity-20 transition-opacity">
                                <Users size={64} />
                            </div>

                            <div className="flex items-start gap-4 mb-4 relative z-10">
                                <div className={clsx(
                                    "p-3 rounded-xl",
                                    customer.type === 'USER' ? "bg-primary/10 text-primary" : "bg-orange-500/10 text-orange-600"
                                )}>
                                    <UserCircle size={28} />
                                </div>
                                <div className="flex-1 min-w-0">
                                    <div className="flex items-center gap-2 flex-wrap">
                                        <h3 className="font-black text-lg line-clamp-1">{customer.name}</h3>
                                        {/* Balance badge right next to the name */}
                                        <span className={clsx(
                                            "text-xs font-black px-2 py-0.5 rounded-full whitespace-nowrap",
                                            Number(customer.balance) > 0
                                                ? "bg-red-500/10 text-red-600 border border-red-500/20"
                                                : "bg-green-500/10 text-green-600 border border-green-500/20"
                                        )}>
                                            {Number(customer.balance) > 0
                                                ? `Owes EGP ${Number(customer.balance).toLocaleString()}`
                                                : 'Settled'}
                                        </span>
                                        {customer.group && (
                                            <span className="bg-primary/10 text-primary text-[10px] font-black px-1.5 py-0.5 rounded uppercase tracking-wider">{customer.group.name}</span>
                                        )}
                                    </div>
                                    <div className="flex items-center gap-1.5 text-muted-foreground text-sm mt-0.5">
                                        <Phone size={14} />
                                        <span>{customer.phone || 'No phone'}</span>
                                    </div>
                                </div>
                            </div>

                            <div className="flex items-start gap-2 text-muted-foreground text-sm mb-6 flex-1 italic line-clamp-2">
                                <MapPin size={16} className="shrink-0 mt-0.5" />
                                <span>{customer.address || "No address on file"}</span>
                            </div>

                            <div className="flex items-center justify-between pt-4 border-t border-border group">
                                <div className="flex items-center gap-2 text-xs font-bold uppercase tracking-tight text-muted-foreground">
                                    <History size={14} />
                                    <span>History Available</span>
                                </div>
                                <Link prefetch={false}
                                    href={`/customers/profile?id=${customer.id}`}
                                    className="flex items-center gap-1.5 px-4 py-2 bg-secondary text-foreground rounded-lg font-bold text-sm hover:bg-primary hover:text-primary-foreground transition-all shadow-sm"
                                >
                                    View Full Profile Ledger
                                    <ExternalLink size={14} />
                                </Link>
                            </div>
                        </div>
                    ))}

                    {filtered.length === 0 && (
                        <div className="col-span-full py-20 text-center bg-secondary/10 border border-dashed border-border rounded-3xl">
                            <Users size={48} className="mx-auto text-muted-foreground/30 mb-4" />
                            <h3 className="text-xl font-bold text-muted-foreground">No customers found</h3>
                            <p className="text-sm text-muted-foreground">Try searching with a different name or phone number</p>
                        </div>
                    )}
                </div>
            )}

            {/* Add Customer Modal */}
            {showAddModal && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-card w-full max-w-md rounded-[2rem] border border-border shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                        <div className="p-8 pb-6 flex flex-col items-center text-center gap-4">
                            <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center text-primary">
                                <UserPlus size={32} strokeWidth={2} />
                            </div>
                            <div>
                                <h3 className="text-2xl font-black tracking-tight mb-1">New Customer</h3>
                                <p className="text-muted-foreground font-medium text-sm">Add a new customer to your database</p>
                            </div>
                        </div>

                        <div className="px-8 pb-6 space-y-4">
                            {formError && (
                                <div className="p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-red-600 text-xs font-bold flex items-center gap-2">
                                    <AlertCircle size={16} className="shrink-0" />
                                    {formError}
                                </div>
                            )}

                            <div>
                                <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1.5 block">Customer Name *</label>
                                <input
                                    type="text"
                                    placeholder="e.g. Ahmed Mohamed"
                                    value={newCustomer.name}
                                    onChange={handleNewCustomerNameChange}
                                    className="w-full p-3 bg-background border border-border/60 rounded-xl text-sm font-medium outline-none focus:border-primary/50 focus:ring-2 focus:ring-primary/10 transition-all"
                                    autoFocus
                                />
                            </div>

                            <div>
                                <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1.5 block">Phone (Optional)</label>
                                <input
                                    type="tel"
                                    placeholder="e.g. 01012345678"
                                    value={newCustomer.phone}
                                    onChange={handleNewCustomerPhoneChange}
                                    className="w-full p-3 bg-background border border-border/60 rounded-xl text-sm font-medium outline-none focus:border-primary/50 focus:ring-2 focus:ring-primary/10 transition-all"
                                />
                            </div>

                            <div>
                                <label className="text-xs font-bold uppercase tracking-wider text-muted-foreground mb-1.5 block">Address (Optional)</label>
                                <input
                                    type="text"
                                    placeholder="e.g. Cairo, Egypt"
                                    value={newCustomer.address}
                                    onChange={handleNewCustomerAddressChange}
                                    className="w-full p-3 bg-background border border-border/60 rounded-xl text-sm font-medium outline-none focus:border-primary/50 focus:ring-2 focus:ring-primary/10 transition-all"
                                />
                            </div>
                        </div>

                        <div className="p-6 bg-secondary/20 flex gap-3">
                            <button
                                onClick={handleCloseAddModal}
                                className="flex-1 py-4 bg-background border border-border/60 rounded-xl font-bold hover:bg-secondary transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleCreateCustomer}
                                disabled={creating}
                                className="flex-1 py-4 bg-primary text-primary-foreground rounded-xl font-black shadow-lg shadow-primary/20 hover:bg-primary/90 hover:scale-[1.02] transition-all disabled:opacity-50 flex items-center justify-center gap-2"
                            >
                                {creating ? (
                                    <Loader2 className="animate-spin" size={20} />
                                ) : (
                                    <>
                                        <Plus size={18} strokeWidth={3} />
                                        Create Customer
                                    </>
                                )}
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useRef, useCallback } from 'react';
import { Search, ShoppingCart, Trash2, Plus, Minus, Loader2, Check, User, ChevronDown, AlertCircle, AlertTriangle, X, CreditCard, Banknote, Smartphone } from 'lucide-react';
import { getProducts, processSale, getCategories, getStaffList } from '@/app/actions/sales';
import { searchCustomers } from '@/app/actions/customers';
import { getCurrentUser } from '@/app/actions/auth';
import clsx from 'clsx';

interface Product {
    id: string;
    name: string;
    sku: string;
    baseSellingPrice: number;
    categoryId: string;
    category?: { id: string; name: string };
    stock: number;
}

interface CartItem {
    product: Product;
    quantity: number;
}

interface Staff {
    id: string;
    name: string | null;
    username: string;
}

interface CustomerSearch {
    id: string;
    name: string;
    phone: string | null;
    address: string | null;
    type: string;
}

type PaymentMethodType = 'CASH' | 'CREDIT' | 'INSTAPAY';

export default function SalesPage() {
    const [cart, setCart] = useState<CartItem[]>([]);
    const [searchQuery, setSearchQuery] = useState('');
    const [categoryFilter, setCategoryFilter] = useState<string>('all');
    const [categories, setCategories] = useState<{ id: string; name: string }[]>([]);
    const [products, setProducts] = useState<Product[]>([]);
    const [loading, setLoading] = useState(true);
    const [processing, setProcessing] = useState(false);
    const [paymentMethod, setPaymentMethod] = useState<PaymentMethodType>('CASH');
    const [showSuccess, setShowSuccess] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const [showConfirmDialog, setShowConfirmDialog] = useState(false);

    // Salesperson
    const [staffList, setStaffList] = useState<Staff[]>([]);
    const [selectedStaffId, setSelectedStaffId] = useState<string>('');

    // Discount & Notes
    const [discount, setDiscount] = useState<number | ''>('');
    const [orderNotes, setOrderNotes] = useState('');

    // Buyer info state
    const [buyerInfo, setBuyerInfo] = useState({
        customerName: '',
        customerPhone: '',
        customerAddress: ''
    });

    // Customer Search State
    const [searchResults, setSearchResults] = useState<CustomerSearch[]>([]);
    const [selectedCustomerId, setSelectedCustomerId] = useState<string | null>(null);
    const [amountPaid, setAmountPaid] = useState<number | ''>('');
    const [showSuggestions, setShowSuggestions] = useState(false);
    const [isSearching, setIsSearching] = useState(false);
    const searchTimeoutRef = useRef<NodeJS.Timeout | null>(null);

    const handleBuyerInfoChange = useCallback((field: string, val: string) => {
        setBuyerInfo(prev => ({ ...prev, [field]: val }));
        if (field !== 'customerName' && field !== 'customerPhone') return;
        if (searchTimeoutRef.current) clearTimeout(searchTimeoutRef.current);
        if (val.length < 2) { setSearchResults([]); setShowSuggestions(false); return; }
        setIsSearching(true);
        searchTimeoutRef.current = setTimeout(async () => {
            const results = await searchCustomers(val);
            setSearchResults(results);
            setShowSuggestions(results.length > 0);
            setIsSearching(false);
        }, 300);
    }, []);

    const selectCustomer = useCallback((cust: CustomerSearch) => {
        setBuyerInfo({ customerName: cust.name, customerPhone: cust.phone || '', customerAddress: cust.address || '' });
        setSelectedCustomerId(cust.id);
        setShowSuggestions(false);
    }, []);

    const clearCustomer = useCallback(() => {
        setBuyerInfo({ customerName: '', customerPhone: '', customerAddress: '' });
        setSelectedCustomerId(null);
    }, []);

    useEffect(() => {
        Promise.all([getProducts(), getCategories(), getStaffList(), getCurrentUser()]).then(([prods, cats, staff, user]) => {
            setProducts(prods);
            setCategories(cats);
            setStaffList(staff);
            setLoading(false);
            if (user && staff.some(s => s.id === user.id)) {
                setSelectedStaffId(user.id);
            }
        });
    }, []);

    const addToCart = useCallback((product: Product) => {
        setCart(prev => {
            const currentInCart = prev.find(item => item.product.id === product.id)?.quantity || 0;
            if (currentInCart >= product.stock) {
                setError(`Cannot add more ${product.name}. Only ${product.stock} in stock.`);
                setTimeout(() => setError(null), 3000);
                return prev;
            }
            const existing = prev.find(item => item.product.id === product.id);
            if (existing) {
                return prev.map(item =>
                    item.product.id === product.id
                        ? { ...item, quantity: item.quantity + 1 }
                        : item
                );
            }
            return [...prev, { product, quantity: 1 }];
        });
    }, []);

    const updateQuantity = useCallback((productId: string, delta: number) => {
        setCart(prev => {
            return prev.map(item => {
                if (item.product.id === productId) {
                    const newQty = item.quantity + delta;
                    if (newQty <= 0) return null;
                    if (delta > 0 && newQty > item.product.stock) {
                        setError(`Cannot add more. Only ${item.product.stock} in stock.`);
                        setTimeout(() => setError(null), 3000);
                        return item;
                    }
                    return { ...item, quantity: newQty };
                }
                return item;
            }).filter(Boolean) as CartItem[];
        });
    }, []);

    const handleCheckoutClick = () => {
        if (cart.length === 0) return;

        // Validation: Require customer data
        if (!selectedCustomerId && !buyerInfo.customerName.trim()) {
            setError('Please enter a customer name or select an existing customer.');
            setTimeout(() => setError(null), 3000);
            return;
        }

        // Validation: Walk-in (non-registered) customers must pay full amount
        if (!selectedCustomerId) {
            if (paymentMethod === 'CASH') {
                const paid = typeof amountPaid === 'number' ? amountPaid : 0;
                if (paid < total) {
                    setError('Walk-in customers must pay the full amount. No debt allowed.');
                    setTimeout(() => setError(null), 3000);
                    return;
                }
            }
            // For CREDIT/INSTAPAY walk-ins, auto-set amountPaid to total (exact payment)
            if (paymentMethod !== 'CASH') {
                setAmountPaid(total);
            }
        }

        setShowConfirmDialog(true);
    };

    const handleConfirmCheckout = async () => {
        setShowConfirmDialog(false);
        setProcessing(true);
        setError(null);
        try {
            const result = await processSale(
                cart.map(item => ({ productId: item.product.id, quantity: item.quantity })),
                paymentMethod,
                buyerInfo.customerName ? buyerInfo : undefined,
                undefined,
                selectedStaffId,
                amountPaid === '' ? undefined : amountPaid,
                selectedCustomerId || undefined
            );

            if (result.success) {
                setShowSuccess(true);
                setCart([]);
                setBuyerInfo({ customerName: '', customerPhone: '', customerAddress: '' });
                setSelectedCustomerId(null);
                setAmountPaid('');
                setDiscount('');
                setOrderNotes('');
                setTimeout(() => setShowSuccess(false), 3000);
                getProducts().then(setProducts);
            } else {
                setError(result.error || 'Failed to process sale.');
            }
        } catch (err) {
            console.error(err);
            setError('Connection error. Please check your internet and try again.');
        } finally {
            setProcessing(false);
        }
    };

    const subtotal = cart.reduce((sum, item) => sum + (item.product.baseSellingPrice * item.quantity), 0);
    const validDiscount = typeof discount === 'number' ? discount : 0;
    const discountAmount = validDiscount > 0 ? (subtotal * validDiscount / 100) : 0;
    const total = subtotal - discountAmount;

    const filteredProducts = products.filter(p => {
        const matchesSearch = p.name.toLowerCase().includes(searchQuery.toLowerCase()) || p.sku.toLowerCase().includes(searchQuery.toLowerCase());
        const matchesCategory = categoryFilter === 'all' || p.categoryId === categoryFilter;
        return matchesSearch && matchesCategory;
    });

    const addQuickCash50 = useCallback(() => setAmountPaid(prev => (typeof prev === 'number' ? prev + 50 : 50)), []);
    const addQuickCash100 = useCallback(() => setAmountPaid(prev => (typeof prev === 'number' ? prev + 100 : 100)), []);
    const addQuickCash200 = useCallback(() => setAmountPaid(prev => (typeof prev === 'number' ? prev + 200 : 200)), []);
    const setExactCash = useCallback(() => setAmountPaid(total), [total]);
    const handleSearchChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setSearchQuery(e.target.value), []);
    const handleNotesChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setOrderNotes(e.target.value), []);
    const handleDiscountChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setDiscount(e.target.value === '' ? '' : Math.min(100, Math.max(0, parseInt(e.target.value) || 0))), []);
    const handleAmountPaidChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setAmountPaid(e.target.value === '' ? '' : parseFloat(e.target.value)), []);
    const handleStaffChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setSelectedStaffId(e.target.value), []);
    const handleCustomerNameChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => handleBuyerInfoChange('customerName', e.target.value), [handleBuyerInfoChange]);
    const handleCustomerPhoneChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => handleBuyerInfoChange('customerPhone', e.target.value), [handleBuyerInfoChange]);
    const handleCustomerAddressChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => handleBuyerInfoChange('customerAddress', e.target.value), [handleBuyerInfoChange]);
    const handleCloseConfirmDialog = useCallback(() => setShowConfirmDialog(false), []);
    const setCategoryAll = useCallback(() => setCategoryFilter('all'), []);

    const handleCategorySelect = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) setCategoryFilter(id);
    }, []);

    const handleAddProductToCart = useCallback((e: React.MouseEvent<HTMLDivElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) {
            const product = products.find(p => p.id === id);
            if (product) {
                if (product.stock === 0) return;
                const quantity = cart.find(item => item.product.id === id)?.quantity || 0;
                if (quantity === 0) addToCart(product);
            }
        }
    }, [products, cart, addToCart]);

    const handleDecrementQuantity = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        e.stopPropagation();
        const id = e.currentTarget.dataset.id;
        if (id) updateQuantity(id, -1);
    }, [updateQuantity]);

    const handleIncrementQuantity = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        e.stopPropagation();
        const id = e.currentTarget.dataset.id;
        if (id) updateQuantity(id, 1);
    }, [updateQuantity]);

    const handleSelectCustomerClick = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) {
            const cust = searchResults.find(c => c.id === id);
            if (cust) selectCustomer(cust);
        }
    }, [searchResults, selectCustomer]);

    const handlePaymentMethodSelect = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const methodId = e.currentTarget.dataset.id as PaymentMethodType;
        if (methodId) {
            setPaymentMethod(methodId);
            if (methodId !== 'CASH') setAmountPaid(total);
            else setAmountPaid('');
        }
    }, [total]);

    return (
        <div className="flex flex-col lg:flex-row h-[calc(100vh-6rem)] gap-6 overflow-hidden max-w-7xl mx-auto w-full pb-4">
            {/* Main Product Area */}
            <div className="flex-1 flex flex-col gap-6 min-w-0">
                {/* Search & Filter Header */}
                <div className="flex flex-col sm:flex-row items-center gap-4 bg-card/60 backdrop-blur-xl p-4 rounded-3xl border border-border/50 shadow-sm">
                    <div className="flex items-center flex-1 w-full bg-background/50 rounded-2xl px-4 py-3 border border-border/50 focus-within:ring-2 focus-within:ring-primary/20 focus-within:border-primary/50 transition-all">
                        <Search className="text-muted-foreground shrink-0 mr-3" size={20} />
                        <input
                            className="bg-transparent outline-none flex-1 text-sm font-medium placeholder:text-muted-foreground/60 w-full"
                            placeholder="Search products by name or SKU..."
                            value={searchQuery}
                            onChange={handleSearchChange}
                        />
                    </div>

                    <div className="w-full sm:w-auto overflow-x-auto pb-1 sm:pb-0 scrollbar-none">
                        <div className="flex items-center gap-2">
                            <button
                                onClick={setCategoryAll}
                                className={clsx(
                                    "px-5 py-2.5 rounded-2xl text-sm font-bold transition-all whitespace-nowrap",
                                    categoryFilter === 'all' 
                                        ? "bg-primary text-primary-foreground shadow-md" 
                                        : "bg-secondary/50 text-muted-foreground hover:bg-secondary hover:text-foreground"
                                )}
                            >
                                All items
                            </button>
                            {categories.map(c => (
                                <button
                                    key={c.id}
                                    data-id={c.id}
                                    onClick={handleCategorySelect}
                                    className={clsx(
                                        "px-5 py-2.5 rounded-2xl text-sm font-bold transition-all whitespace-nowrap",
                                        categoryFilter === c.id 
                                            ? "bg-primary text-primary-foreground shadow-md" 
                                            : "bg-secondary/50 text-muted-foreground hover:bg-secondary hover:text-foreground"
                                    )}
                                >
                                    {c.name}
                                </button>
                            ))}
                        </div>
                    </div>
                </div>

                {/* Product Grid */}
                <div className="flex-1 overflow-y-auto rounded-3xl pr-2">
                    {loading ? (
                        <div className="flex flex-col items-center justify-center h-full text-muted-foreground/60 gap-4">
                            <div className="p-4 bg-secondary/30 rounded-full">
                                <Loader2 className="animate-spin" size={32} />
                            </div>
                            <span className="font-medium">Loading inventory...</span>
                        </div>
                    ) : (
                        <div className="grid grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4 pb-20">
                            {filteredProducts.map(product => {
                                const cartItem = cart.find(item => item.product.id === product.id);
                                const quantity = cartItem?.quantity || 0;
                                const isOutOfStock = product.stock === 0;
                                const isLowStock = product.stock > 0 && product.stock <= 5;

                                return (
                                    <div
                                        key={product.id}
                                        data-id={product.id}
                                        onClick={handleAddProductToCart}
                                        className={clsx(
                                            "group flex flex-col p-4 bg-card/40 backdrop-blur-sm border rounded-3xl relative overflow-hidden transition-all duration-300",
                                            isOutOfStock ? "border-red-200/50 bg-red-50/10 opacity-75" : "border-border/50 hover:border-primary/30 hover:shadow-xl hover:shadow-primary/5 cursor-pointer"
                                        )}
                                    >
                                        {/* Status Badges */}
                                        <div className="absolute top-3 left-3 flex flex-col gap-2 z-10">
                                            {isOutOfStock && (
                                                <div className="bg-red-500/90 backdrop-blur-md text-white px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-wider shadow-sm flex items-center gap-1">
                                                    <X size={10} strokeWidth={3} /> Sold Out
                                                </div>
                                            )}
                                            {isLowStock && !isOutOfStock && (
                                                <div className="bg-amber-500/90 backdrop-blur-md text-white px-2.5 py-1 rounded-full text-[10px] font-black uppercase tracking-wider shadow-sm flex items-center gap-1">
                                                    <AlertTriangle size={10} strokeWidth={3} /> {product.stock} Left
                                                </div>
                                            )}
                                        </div>

                                        {/* Product Image Placeholder */}
                                        <div className={clsx(
                                            "w-full aspect-square rounded-2xl mb-4 flex items-center justify-center text-5xl font-black transition-all duration-500 relative overflow-hidden",
                                            isOutOfStock ? "bg-muted/30 text-muted-foreground/20" : "bg-gradient-to-br from-primary/5 to-primary/10 text-primary/40 group-hover:scale-105"
                                        )}>
                                            {product.name.charAt(0)}
                                            <div className="absolute inset-0 bg-gradient-to-t from-background/80 to-transparent opacity-0 group-hover:opacity-100 transition-opacity duration-300" />
                                        </div>

                                        {/* Product Details */}
                                        <div className="flex flex-col flex-1">
                                            <div className="font-bold text-base line-clamp-1 group-hover:text-primary transition-colors">{product.name}</div>
                                            <div className="text-xs text-muted-foreground font-medium uppercase tracking-wider mt-1">{product.sku}</div>

                                            <div className="mt-auto pt-4 flex items-end justify-between gap-2">
                                                <div className="flex flex-col">
                                                    <span className="text-[10px] text-muted-foreground uppercase font-bold tracking-wider">Price</span>
                                                    <span className="font-black text-lg">EGP {product.baseSellingPrice.toLocaleString()}</span>
                                                </div>

                                                {/* Quantity Controls */}
                                                {!isOutOfStock && (
                                                    <div className={clsx(
                                                        "transition-all duration-300 overflow-hidden",
                                                        quantity > 0 ? "opacity-100 translate-y-0" : "opacity-0 translate-y-4 absolute right-4 bottom-4 pointer-events-none group-hover:opacity-100 group-hover:translate-y-0 group-hover:pointer-events-auto"
                                                    )}>
                                                        {quantity > 0 ? (
                                                            <div className="flex items-center gap-1 bg-primary/10 p-1 rounded-xl border border-primary/20 backdrop-blur-md">
                                                                <button
                                                                    data-id={product.id}
                                                                    onClick={handleDecrementQuantity}
                                                                    className="w-8 h-8 flex items-center justify-center bg-background rounded-lg hover:bg-red-50 hover:text-red-500 shadow-sm transition-all"
                                                                >
                                                                    {quantity === 1 ? <Trash2 size={14} /> : <Minus size={14} strokeWidth={3} />}
                                                                </button>
                                                                <span className="w-8 text-center font-black text-primary">{quantity}</span>
                                                                <button
                                                                    data-id={product.id}
                                                                    onClick={handleIncrementQuantity}
                                                                    disabled={quantity >= product.stock}
                                                                    className="w-8 h-8 flex items-center justify-center bg-primary text-primary-foreground rounded-lg shadow-sm hover:bg-primary/90 transition-all disabled:opacity-50 disabled:bg-primary"
                                                                >
                                                                    <Plus size={14} strokeWidth={3} />
                                                                </button>
                                                            </div>
                                                        ) : (
                                                            <div className="w-10 h-10 bg-primary text-primary-foreground rounded-xl flex items-center justify-center shadow-lg hover:scale-110 transition-transform">
                                                                <Plus size={20} strokeWidth={3} />
                                                            </div>
                                                        )}
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                );
                            })}
                        </div>
                    )}
                </div>
            </div>

            {/* Sidebar / Checkout Pane */}
            <div className="w-full lg:w-[420px] flex flex-col h-full shrink-0">
                <div className="bg-card/80 backdrop-blur-2xl border border-border/50 rounded-3xl flex flex-col h-full shadow-2xl overflow-hidden relative">

                    {/* Top Header & Cashier */}
                    <div className="px-6 py-4 flex items-center justify-between border-b border-border/30 bg-background/50">
                        <div className="flex items-center gap-2">
                            <div className="p-2 bg-primary/10 rounded-xl">
                                <ShoppingCart size={20} className="text-primary" />
                            </div>
                            <span className="font-extrabold text-lg">Current Order</span>
                        </div>
                        <div className="flex flex-col items-end">
                            <span className="text-[10px] text-muted-foreground font-bold uppercase tracking-wider">Cashier</span>
                            <select
                                value={selectedStaffId}
                                onChange={handleStaffChange}
                                className="bg-transparent text-sm font-bold text-primary outline-none cursor-pointer text-right max-w-[120px] truncate"
                            >
                                <option value="" disabled>Select Staff</option>
                                {staffList.map(emp => (
                                    <option key={emp.id} value={emp.id}>{emp.name || emp.username}</option>
                                ))}
                            </select>
                        </div>
                    </div>

                    {/* Customer Section */}
                    <div className="px-6 py-4 border-b border-border/30 bg-muted/10 relative z-20">
                        {!selectedCustomerId ? (
                            <div className="relative">
                                <div className="flex items-center bg-background border border-border/60 rounded-xl p-1 focus-within:ring-2 focus-within:ring-primary/20 transition-all">
                                    <div className="pl-3 text-muted-foreground">
                                        {isSearching ? <Loader2 size={16} className="animate-spin" /> : <User size={16} />}
                                    </div>
                                    <input
                                        type="text"
                                        placeholder="Add customer (Search by name or phone)"
                                        value={buyerInfo.customerName}
                                        onChange={handleCustomerNameChange}
                                        className="w-full bg-transparent p-2 text-sm outline-none font-medium placeholder:text-muted-foreground/60"
                                    />
                                </div>

                                {showSuggestions && searchResults.length > 0 && (
                                    <div className="absolute top-full left-0 right-0 mt-2 bg-popover border border-border/50 rounded-2xl shadow-xl overflow-hidden animate-in slide-in-from-top-2">
                                        {searchResults.map((cust, idx) => (
                                            <button
                                                key={idx}
                                                data-id={cust.id}
                                                onClick={handleSelectCustomerClick}
                                                className="w-full text-left px-4 py-3 hover:bg-secondary/50 border-b border-border/20 last:border-0 transition-colors flex items-center justify-between"
                                            >
                                                <div>
                                                    <div className="font-bold text-sm flex items-center gap-2">
                                                        {cust.name}
                                                        {cust.type === 'USER' && <span className="bg-primary/10 text-primary px-1.5 py-0.5 rounded-md text-[9px] font-black uppercase">Member</span>}
                                                    </div>
                                                    {cust.phone && <div className="text-xs text-muted-foreground mt-0.5 font-medium">{cust.phone}</div>}
                                                </div>
                                                <ChevronDown size={16} className="text-muted-foreground -rotate-90" />
                                            </button>
                                        ))}
                                    </div>
                                )}

                                {/* Quick inline manual info if no results but typed something */}
                                {buyerInfo.customerName.length > 2 && !showSuggestions && !isSearching && (
                                    <div className="mt-3 p-3 bg-primary/5 rounded-xl border border-primary/10 space-y-2 animate-in fade-in">
                                        <div className="text-xs font-bold text-primary mb-2 flex items-center gap-1">
                                            <Plus size={12} /> New Customer Entry
                                        </div>
                                        <div className="flex gap-2">
                                            <input
                                                type="tel"
                                                placeholder="Phone (Optional)"
                                                value={buyerInfo.customerPhone}
                                                onChange={handleCustomerPhoneChange}
                                                className="w-1/2 p-2 text-xs rounded-lg border border-border/50 bg-background outline-none focus:border-primary/50"
                                            />
                                            <input
                                                type="text"
                                                placeholder="Address (Optional)"
                                                value={buyerInfo.customerAddress}
                                                onChange={handleCustomerAddressChange}
                                                className="w-1/2 p-2 text-xs rounded-lg border border-border/50 bg-background outline-none focus:border-primary/50"
                                            />
                                        </div>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="flex items-center justify-between bg-primary/5 border border-primary/20 p-3 rounded-xl">
                                <div className="flex items-center gap-3">
                                    <div className="w-10 h-10 bg-primary/10 rounded-full flex items-center justify-center text-primary font-bold">
                                        {buyerInfo.customerName.charAt(0)}
                                    </div>
                                    <div>
                                        <div className="font-bold text-sm leading-tight">{buyerInfo.customerName}</div>
                                        {buyerInfo.customerPhone && <div className="text-xs text-muted-foreground font-medium">{buyerInfo.customerPhone}</div>}
                                    </div>
                                </div>
                                <button onClick={clearCustomer} className="p-2 text-muted-foreground hover:bg-red-50 hover:text-red-500 rounded-lg transition-colors">
                                    <X size={16} />
                                </button>
                            </div>
                        )}
                    </div>

                    {/* Cart Items List */}
                    <div className="flex-1 overflow-y-auto px-6 py-2">
                        {error && (
                            <div className="mb-4 p-3 bg-red-500/10 border border-red-500/20 rounded-xl text-red-600 text-xs font-bold flex items-center gap-2 animate-in slide-in-from-top-1">
                                <AlertCircle size={16} className="shrink-0" />
                                {error}
                            </div>
                        )}

                        {cart.length === 0 ? (
                            <div className="h-full flex flex-col items-center justify-center text-muted-foreground/40 gap-4">
                                <div className="w-24 h-24 rounded-full bg-secondary/50 flex items-center justify-center mb-2">
                                    <ShoppingCart size={40} strokeWidth={1.5} />
                                </div>
                                <div className="font-medium">Scan or add items to cart</div>
                            </div>
                        ) : (
                            <div className="space-y-1">
                                {cart.map(item => (
                                    <div key={item.product.id} className="group flex gap-4 py-3 border-b border-border/40 last:border-0 items-center">
                                        <div className="flex-1 min-w-0">
                                            <div className="font-bold text-sm text-foreground truncate">{item.product.name}</div>
                                            <div className="text-xs text-muted-foreground font-medium mt-0.5">EGP {item.product.baseSellingPrice.toLocaleString()}</div>
                                        </div>

                                        <div className="flex items-center gap-3 bg-secondary/50 p-1 rounded-xl">
                                            <button data-id={item.product.id} onClick={handleDecrementQuantity} className="w-7 h-7 flex items-center justify-center rounded-lg hover:bg-background shadow-sm transition-all text-muted-foreground hover:text-foreground">
                                                <Minus size={14} strokeWidth={2.5} />
                                            </button>
                                            <span className="font-black text-sm w-4 text-center">{item.quantity}</span>
                                            <button data-id={item.product.id} onClick={handleIncrementQuantity} disabled={item.quantity >= item.product.stock} className="w-7 h-7 flex items-center justify-center rounded-lg hover:bg-background shadow-sm transition-all text-muted-foreground hover:text-foreground disabled:opacity-30">
                                                <Plus size={14} strokeWidth={2.5} />
                                            </button>
                                        </div>

                                        <div className="text-right w-20 shrink-0">
                                            <div className="font-black text-sm">EGP {(item.product.baseSellingPrice * item.quantity).toLocaleString()}</div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                        )}
                    </div>

                    {/* Checkout Details & Actions */}
                    <div className="bg-background/80 backdrop-blur-xl border-t border-border/50 p-6 flex flex-col gap-4 z-20">
                        {/* Discount & Notes */}
                        <div className="flex gap-3">
                            <div className="relative flex-1">
                                <input
                                    type="text"
                                    placeholder="Add note..."
                                    value={orderNotes}
                                    onChange={handleNotesChange}
                                    className="w-full bg-secondary/30 border border-border/50 p-3 rounded-xl text-sm font-medium outline-none focus:border-primary/50 transition-colors"
                                />
                            </div>
                            <div className="relative w-28 shrink-0 group">
                                <input
                                    type="number"
                                    placeholder="Disc %"
                                    value={discount}
                                    onChange={handleDiscountChange}
                                    className="w-full bg-secondary/30 border border-border/50 p-3 pl-8 rounded-xl text-sm font-bold outline-none focus:border-primary/50 transition-colors"
                                />
                                <div className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground group-focus-within:text-primary font-bold">%</div>
                            </div>
                        </div>

                        {/* Totals */}
                        <div className="space-y-1.5 pt-2">
                            <div className="flex justify-between text-sm font-medium text-muted-foreground">
                                <span>Subtotal</span>
                                <span>EGP {subtotal.toLocaleString()}</span>
                            </div>
                            {validDiscount > 0 && (
                                <div className="flex justify-between text-sm font-bold text-red-500">
                                    <span>Discount ({validDiscount}%)</span>
                                    <span>-EGP {discountAmount.toLocaleString()}</span>
                                </div>
                            )}
                            <div className="flex justify-between items-end pt-3 pb-1">
                                <span className="font-bold text-muted-foreground uppercase tracking-wider text-xs mb-1">Total Due</span>
                                <span className="font-black text-4xl tracking-tight">EGP {total.toLocaleString()}</span>
                            </div>
                        </div>

                        {/* Payment Type Selection (Segmented Control) */}
                        <div className="bg-secondary/50 p-1.5 rounded-2xl flex gap-1 relative">
                            {[
                                { id: 'CASH', icon: Banknote, label: 'Cash' },
                                { id: 'CREDIT', icon: CreditCard, label: 'Card' },
                                { id: 'INSTAPAY', icon: Smartphone, label: 'InstaPay' }
                            ].map((method) => {
                                const isActive = paymentMethod === method.id;
                                const Icon = method.icon;
                                return (
                                    <button
                                        key={method.id}
                                        data-id={method.id}
                                        onClick={handlePaymentMethodSelect}
                                        className={clsx(
                                            "flex-1 flex flex-col items-center justify-center py-2.5 rounded-xl font-bold text-xs transition-all duration-300 relative z-10 gap-1",
                                            isActive ? "text-foreground shadow-sm" : "text-muted-foreground hover:text-foreground"
                                        )}
                                    >
                                        {isActive && <div className="absolute inset-0 bg-background rounded-xl -z-10 shadow-sm" />}
                                        <Icon size={16} />
                                        {method.label}
                                    </button>
                                );
                            })}
                        </div>

                        {/* Amount Paid section (Prominent for cash) */}
                        {paymentMethod === 'CASH' && (
                            <div className="space-y-3 animate-in fade-in slide-in-from-top-2">
                                <div className="relative">
                                    <span className="absolute left-4 top-1/2 -translate-y-1/2 font-black text-muted-foreground">EGP</span>
                                    <input
                                        type="number"
                                        placeholder="Amount Tendered"
                                        value={amountPaid}
                                        onChange={handleAmountPaidChange}
                                        className="w-full bg-background border-2 border-primary/20 p-4 pl-14 rounded-2xl text-xl font-black outline-none focus:border-primary focus:ring-4 focus:ring-primary/10 transition-all text-right"
                                    />
                                    {typeof amountPaid === 'number' && amountPaid > total && (
                                        <div className="absolute right-4 -top-3 bg-green-500 text-white text-[10px] font-black px-2 py-0.5 rounded-full shadow-sm">
                                            Change: EGP {(amountPaid - total).toLocaleString()}
                                        </div>
                                    )}
                                </div>

                                {/* Quick Cash Buttons */}
                                <div className="grid grid-cols-4 gap-2">
                                    <button onClick={setExactCash} className="py-2 bg-secondary text-foreground font-bold text-xs rounded-xl hover:bg-secondary/80 transition-colors">Exact</button>
                                    <button onClick={addQuickCash50} className="py-2 bg-secondary text-foreground font-bold text-xs rounded-xl hover:bg-secondary/80 transition-colors">+50</button>
                                    <button onClick={addQuickCash100} className="py-2 bg-secondary text-foreground font-bold text-xs rounded-xl hover:bg-secondary/80 transition-colors">+100</button>
                                    <button onClick={addQuickCash200} className="py-2 bg-secondary text-foreground font-bold text-xs rounded-xl hover:bg-secondary/80 transition-colors">+200</button>
                                </div>
                            </div>
                        )}

                        {/* Checkout CTA */}
                        <button
                            onClick={handleCheckoutClick}
                            disabled={processing || cart.length === 0}
                            className={clsx(
                                "w-full h-16 rounded-2xl font-black text-lg flex items-center justify-center gap-2 transition-all duration-300 shadow-lg relative overflow-hidden group mt-2",
                                cart.length === 0 
                                    ? "bg-secondary text-muted-foreground shadow-none cursor-not-allowed" 
                                    : "bg-primary text-primary-foreground hover:shadow-xl hover:shadow-primary/20 hover:-translate-y-0.5"
                            )}
                        >
                            <div className="absolute inset-0 w-full h-full bg-white/20 scale-x-0 group-hover:scale-x-100 origin-left transition-transform duration-500 ease-out" />
                            {processing ? (
                                <Loader2 className="animate-spin" size={24} />
                            ) : (
                                <>
                                    Complete Sale
                                    <div className="bg-white/20 p-1 rounded-lg ml-2">
                                        <Check size={18} strokeWidth={3} />
                                    </div>
                                </>
                            )}
                        </button>
                    </div>
                </div>
            </div>

            {/* Confirmation Dialog */}
            {showConfirmDialog && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-background/80 backdrop-blur-sm animate-in fade-in duration-200">
                    <div className="bg-card w-full max-w-md rounded-[2rem] border border-border shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200">
                        <div className="p-8 pb-6 flex flex-col items-center text-center gap-4">
                            <div className="w-16 h-16 bg-primary/10 rounded-full flex items-center justify-center text-primary">
                                <ShoppingCart size={32} strokeWidth={2} />
                            </div>
                            <div>
                                <h3 className="text-2xl font-black tracking-tight mb-1">Confirm Sale</h3>
                                <p className="text-muted-foreground font-medium text-sm">Review the transaction details before completing.</p>
                            </div>
                        </div>

                        <div className="px-8 pb-6 space-y-4">
                            <div className="bg-secondary/50 p-5 rounded-2xl space-y-3">
                                <div className="flex justify-between text-sm font-medium">
                                    <span className="text-muted-foreground">Items</span>
                                    <span className="font-bold">{cart.length}</span>
                                </div>
                                <div className="flex justify-between text-sm font-medium">
                                    <span className="text-muted-foreground">Payment Method</span>
                                    <span className="font-bold">{paymentMethod}</span>
                                </div>
                                {buyerInfo.customerName && (
                                    <div className="flex justify-between text-sm font-medium">
                                        <span className="text-muted-foreground">Customer</span>
                                        <span className="font-bold text-right">{buyerInfo.customerName}</span>
                                    </div>
                                )}
                                <div className="h-px bg-border my-2" />
                                <div className="flex justify-between font-black text-xl">
                                    <span>Total Due</span>
                                    <span className="text-primary">EGP {total.toLocaleString()}</span>
                                </div>
                                {paymentMethod === 'CASH' && amountPaid && typeof amountPaid === 'number' && (
                                    <div className="flex justify-between font-bold text-sm text-green-600 pt-1">
                                        <span>Change</span>
                                        <span>EGP {Math.max(0, amountPaid - total).toLocaleString()}</span>
                                    </div>
                                )}
                            </div>
                        </div>

                        <div className="p-6 bg-secondary/20 flex gap-3">
                            <button
                                onClick={handleCloseConfirmDialog}
                                className="flex-1 py-4 bg-background border border-border/60 rounded-xl font-bold hover:bg-secondary transition-colors"
                            >
                                Cancel
                            </button>
                            <button
                                onClick={handleConfirmCheckout}
                                className="flex-1 py-4 bg-primary text-primary-foreground rounded-xl font-black shadow-lg shadow-primary/20 hover:bg-primary/90 hover:scale-[1.02] transition-all"
                            >
                                Confirm Sale
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Success Animation Overlay */}
            {showSuccess && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-background/90 backdrop-blur-md animate-in fade-in duration-300">
                    <div className="flex flex-col items-center gap-6 animate-in zoom-in-50 duration-500 ease-out">
                        <div className="w-28 h-28 bg-green-500 rounded-full flex items-center justify-center text-white shadow-2xl shadow-green-500/30 ring-8 ring-green-500/20">
                            <Check size={56} strokeWidth={4} />
                        </div>
                        <div className="text-center space-y-2">
                            <h2 className="text-4xl font-black tracking-tight text-foreground">Sale Complete!</h2>
                            <p className="text-lg text-muted-foreground font-medium">The invoice has been successfully recorded.</p>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useRef, Fragment, useCallback } from 'react';
import { UserCheck, Trophy, Phone, Eye, X, FileDown, Calendar, DollarSign } from 'lucide-react';
import { getStaffList, getStaffSalesDetail } from '@/app/actions/staff';
import clsx from 'clsx';

type Period = 'day' | 'week' | 'month' | '2months' | '6months' | 'all';

interface StaffMember {
    id: string;
    name: string | null;
    username: string;
    phone?: string | null;
}

interface Invoice {
    id: string;
    date: Date | string;
    customerName: string | null;
    totalAmount: number | string | { toNumber: () => number };
}

interface StaffSalesDetail {
    totalSales: number;
    totalTransactions: number;
    invoices: Invoice[];
}

const periodLabels: Record<Period, string> = {
    day: 'Today',
    week: 'This Week',
    month: 'This Month',
    '2months': '2 Months',
    '6months': '6 Months',
    all: 'All Time'
};

export default function StaffSalesPage() {
    const [staff, setStaff] = useState<StaffMember[]>([]);
    const [salesData, setSalesData] = useState<Record<string, { total: number, count: number }>>({});
    const [loading, setLoading] = useState(true);

    // Modal state
    const [selectedStaff, setSelectedStaff] = useState<StaffMember | null>(null);
    const [modalPeriod, setModalPeriod] = useState<Period>('month');
    const [modalData, setModalData] = useState<StaffSalesDetail | null>(null);
    const [modalLoading, setModalLoading] = useState(false);

    const printRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        loadData();
    }, []);

    const loadData = useCallback(async () => {
        setLoading(true);
        try {
            const staffList = await getStaffList();
            setStaff(staffList);

            // Get summary sales for each staff
            const summaryData: Record<string, { total: number, count: number }> = {};
            for (const s of staffList) {
                const detail = await getStaffSalesDetail(s.id, 'all');
                summaryData[s.id] = { total: detail.totalSales, count: detail.totalTransactions };
            }
            setSalesData(summaryData);
        } finally {
            setLoading(false);
        }
    }, []);

    const openModal = useCallback(async (staffMember: StaffMember) => {
        setSelectedStaff(staffMember);
        setModalPeriod('month');
        setModalLoading(true);
        const data = await getStaffSalesDetail(staffMember.id, 'month');
        setModalData(data);
        setModalLoading(false);
    }, []);

    const changePeriod = useCallback(async (period: Period) => {
        if (!selectedStaff) return;
        setModalPeriod(period);
        setModalLoading(true);
        const data = await getStaffSalesDetail(selectedStaff.id, period);
        setModalData(data);
        setModalLoading(false);
    }, [selectedStaff]);

    const handleOpenModal = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) {
            const found = staff.find(s => s.id === id);
            if (found) openModal(found);
        }
    }, [staff, openModal]);

    const handleChangePeriod = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const p = e.currentTarget.dataset.period as Period;
        if (p) changePeriod(p);
    }, [changePeriod]);

    const handleCloseModal = useCallback(() => setSelectedStaff(null), []);

    const exportPDF = useCallback(() => {
        if (!printRef.current || !selectedStaff) return;

        // Use window.print() for simple PDF export
        const printContent = printRef.current.innerHTML;
        const printWindow = window.open('', '_blank');
        if (printWindow) {
            printWindow.document.write(`
                <html>
                <head>
                    <title>Staff Report - ${selectedStaff.name || selectedStaff.username}</title>
                    <style>
                        body { font-family: Arial, sans-serif; padding: 20px; }
                        table { width: 100%; border-collapse: collapse; margin-top: 20px; }
                        th, td { border: 1px solid #ddd; padding: 8px; text-align: left; }
                        th { background-color: #f5f5f5; }
                        .header { border-bottom: 2px solid #333; padding-bottom: 10px; margin-bottom: 20px; }
                        .stats { display: flex; gap: 40px; margin: 20px 0; }
                        .stat { }
                        .stat-label { color: #666; font-size: 12px; }
                        .stat-value { font-size: 24px; font-weight: bold; }
                    </style>
                </head>
                <body>
                    <div class="header">
                        <h1>Staff Sales Report</h1>
                        <p><strong>${selectedStaff.name || selectedStaff.username}</strong></p>
                        <p>Phone: ${selectedStaff.phone || 'N/A'}</p>
                        <p>Period: ${periodLabels[modalPeriod]}</p>
                        <p>Generated: ${new Date().toLocaleString()}</p>
                    </div>
                    ${printContent}
                </body>
                </html>
            `);
            printWindow.document.close();
            printWindow.print();
        }
    }, [selectedStaff, modalPeriod]);

    // Sort staff by total sales
    const sortedStaff = [...staff].sort((a, b) => {
        const aTotal = salesData[a.id]?.total || 0;
        const bTotal = salesData[b.id]?.total || 0;
        return bTotal - aTotal;
    });

    return (
        <div className="space-y-6">
            <div className="flex flex-col sm:flex-row items-start sm:items-center justify-between gap-4">
                <div>
                    <h2 className="text-3xl font-bold tracking-tight text-foreground flex items-center gap-3">
                        <UserCheck className="text-primary" />
                        Staff Sales
                    </h2>
                    <p className="text-muted-foreground">Performance Tracking</p>
                </div>
            </div>

            <div className="rounded-xl border border-border bg-card shadow-sm overflow-hidden">
                <table className="w-full text-sm text-left">
                    <thead className="bg-secondary/30 text-muted-foreground font-semibold border-b border-border">
                        <tr>
                            <th className="px-6 py-4">Rank</th>
                            <th className="px-6 py-4">Staff Member</th>
                            <th className="px-6 py-4">Phone</th>
                            <th className="px-6 py-4 text-right">Transactions</th>
                            <th className="px-6 py-4 text-right">Total Sales (EGP)</th>
                            <th className="px-6 py-4 text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                        {loading ? (
                            <tr><td colSpan={6} className="px-6 py-12 text-center text-muted-foreground">Loading staff data...</td></tr>
                        ) : sortedStaff.length === 0 ? (
                            <tr><td colSpan={6} className="px-6 py-12 text-center text-muted-foreground">No staff members found.</td></tr>
                        ) : (
                            sortedStaff.map((s, index) => (
                                <tr key={s.id} className="hover:bg-muted/50 transition-colors">
                                    <td className="px-6 py-4">
                                        {index === 0 ? (
                                            <Trophy className="text-yellow-500" size={20} />
                                        ) : index === 1 ? (
                                            <Trophy className="text-gray-400" size={20} />
                                        ) : index === 2 ? (
                                            <Trophy className="text-amber-700" size={20} />
                                        ) : (
                                            <span className="text-muted-foreground font-bold">{index + 1}</span>
                                        )}
                                    </td>
                                    <td className="px-6 py-4 font-semibold">{s.name || s.username}</td>
                                    <td className="px-6 py-4 text-muted-foreground">{s.phone || '—'}</td>
                                    <td className="px-6 py-4 text-right">{salesData[s.id]?.count || 0}</td>
                                    <td className="px-6 py-4 text-right font-bold text-green-600">
                                        {(salesData[s.id]?.total || 0).toLocaleString()}
                                    </td>
                                    <td className="px-6 py-4 text-right">
                                        <button
                                            data-id={s.id}
                                            onClick={handleOpenModal}
                                            className="p-2 hover:bg-secondary rounded-lg text-primary"
                                            title="View Details"
                                        >
                                            <Eye size={16} />
                                        </button>
                                    </td>
                                </tr>
                            ))
                        )}
                    </tbody>
                </table>
            </div>

            {/* Staff Detail Modal */}
            {selectedStaff && (
                <div className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/60 backdrop-blur-sm">
                    <div className="bg-card w-full max-w-3xl rounded-2xl border border-border shadow-2xl overflow-hidden max-h-[90vh] flex flex-col">
                        <div className="p-6 border-b border-border flex items-center justify-between bg-primary/5">
                            <div>
                                <h3 className="text-xl font-bold">{selectedStaff.name || selectedStaff.username}</h3>
                                {selectedStaff.phone && (
                                    <p className="text-sm text-muted-foreground flex items-center gap-1">
                                        <Phone size={12} /> {selectedStaff.phone}
                                    </p>
                                )}
                            </div>
                            <div className="flex gap-2">
                                <button
                                    onClick={exportPDF}
                                    className="flex items-center gap-2 px-3 py-2 bg-primary/10 text-primary rounded-lg hover:bg-primary/20 text-sm font-medium"
                                >
                                    <FileDown size={16} />
                                    Export PDF
                                </button>
                                <button onClick={handleCloseModal} className="p-2 hover:bg-secondary rounded-full">
                                    <X size={20} />
                                </button>
                            </div>
                        </div>

                        {/* Period Tabs */}
                        <div className="flex gap-2 p-4 border-b border-border overflow-x-auto">
                            {(Object.keys(periodLabels) as Period[]).map(p => (
                                <button
                                    key={p}
                                    data-period={p}
                                    onClick={handleChangePeriod}
                                    className={clsx(
                                        "px-4 py-2 rounded-lg text-sm font-bold whitespace-nowrap transition-all",
                                        modalPeriod === p
                                            ? "bg-primary text-primary-foreground"
                                            : "bg-secondary text-muted-foreground hover:bg-secondary/80"
                                    )}
                                >
                                    {periodLabels[p]}
                                </button>
                            ))}
                        </div>

                        {/* Stats Summary */}
                        <div className="p-6 grid grid-cols-2 gap-4">
                            <div className="bg-secondary/30 rounded-xl p-4">
                                <div className="flex items-center gap-2 text-muted-foreground text-sm mb-1">
                                    <Calendar size={14} />
                                    Transactions
                                </div>
                                <div className="text-2xl font-black">
                                    {modalLoading ? '...' : modalData?.totalTransactions || 0}
                                </div>
                            </div>
                            <div className="bg-green-50 dark:bg-green-950/20 rounded-xl p-4">
                                <div className="flex items-center gap-2 text-green-600 text-sm mb-1">
                                    <DollarSign size={14} />
                                    Total Sales
                                </div>
                                <div className="text-2xl font-black text-green-600">
                                    EGP {modalLoading ? '...' : (modalData?.totalSales || 0).toLocaleString()}
                                </div>
                            </div>
                        </div>

                        {/* Invoices List */}
                        <div ref={printRef} className="flex-1 overflow-y-auto px-6 pb-6">
                            <table className="w-full text-sm">
                                <thead className="sticky top-0 bg-card">
                                    <tr className="border-b border-border">
                                        <th className="py-2 text-left font-semibold">Date</th>
                                        <th className="py-2 text-left font-semibold">Customer</th>
                                        <th className="py-2 text-right font-semibold">Amount</th>
                                    </tr>
                                </thead>
                                <tbody className="divide-y divide-border">
                                    {modalLoading ? (
                                        <tr><td colSpan={3} className="py-8 text-center text-muted-foreground">Loading...</td></tr>
                                    ) : !modalData?.invoices?.length ? (
                                        <tr><td colSpan={3} className="py-8 text-center text-muted-foreground">No sales in this period.</td></tr>
                                    ) : (
                                        modalData.invoices.map((inv: any) => (
                                            <Fragment key={inv.id}>
                                                <tr className="hover:bg-muted/30">
                                                    <td className="py-2 font-medium">{new Date(inv.date).toLocaleDateString()}</td>
                                                    <td className="py-2">{inv.customerName || '—'}</td>
                                                    <td className="py-2 text-right font-bold text-green-600">
                                                        +{Number(inv.totalAmount).toLocaleString()}
                                                    </td>
                                                </tr>
                                                {/* Detailed Items Row */}
                                                <tr className="bg-secondary/10">
                                                    <td colSpan={3} className="pl-4 pr-2 pb-4 pt-1">
                                                        <div className="text-xs text-muted-foreground ml-2 border-l-2 border-primary/20 pl-3">
                                                            {inv.items?.map((item: any) => (
                                                                <div key={item.id} className="flex justify-between py-1 border-b border-border/50 last:border-0">
                                                                    <span>
                                                                        <span className="font-semibold text-foreground">{item.product?.name || 'Unknown'}</span>
                                                                        <span className="text-muted-foreground mx-1">x</span>
                                                                        {item.quantity}
                                                                        {item.product?.unit && <span className="text-[10px] ml-1 opacity-70">({item.product.unit})</span>}
                                                                    </span>
                                                                    <span>{Number(item.subtotal).toLocaleString()}</span>
                                                                </div>
                                                            ))}
                                                        </div>
                                                    </td>
                                                </tr>
                                            </Fragment>
                                        ))
                                    )}
                                </tbody>
                            </table>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';

import { useState, useEffect, useCallback } from 'react';
import { getUsers, deleteUser, createUser, updateUser } from '@/app/actions/users';
import { getDefaultPermissions, ALL_PERMISSIONS } from '@/lib/permissions';
import { UserPlus, Trash2, Shield, Eye, Phone, MapPin, Settings } from 'lucide-react';
import Link from 'next/link';

interface User {
    id: string;
    username: string;
    name: string | null;
    role: string;
    phone: string | null;
    address: string | null;
    permissions: string[];
    createdAt: Date;
}

const ROLE_COLORS: Record<string, string> = {
    ROOT: 'bg-purple-100 text-purple-700 border-purple-200',
    ADMIN: 'bg-blue-100 text-blue-700 border-blue-200',
    ACCOUNTANT: 'bg-green-100 text-green-700 border-green-200',
    SALESPERSON: 'bg-orange-100 text-orange-700 border-orange-200',
    READ_ONLY: 'bg-gray-100 text-gray-700 border-gray-200',
};

export default function UsersPage() {
    const [users, setUsers] = useState<User[]>([]);
    const [isLoading, setIsLoading] = useState(true);
    const [isModalOpen, setIsModalOpen] = useState(false);
    const [editingUser, setEditingUser] = useState<User | null>(null);
    const [selectedRole, setSelectedRole] = useState('SALESPERSON');
    const [selectedPermissions, setSelectedPermissions] = useState<string[]>([]);
    const [useCustomPermissions, setUseCustomPermissions] = useState(false);
    const [error, setError] = useState('');

    const fetchUsers = useCallback(async (showLoading = false) => {
        if (showLoading) setIsLoading(true);
        const data = await getUsers();
        setUsers(data as User[]);
        setIsLoading(false);
    }, []);

    useEffect(() => {
        // eslint-disable-next-line react-hooks/set-state-in-effect
        void fetchUsers(false);
    }, [fetchUsers]);

    // permissions derived directly when needed

    const handleDelete = async (id: string) => {
        if (confirm('Are you sure you want to delete this user?')) {
            const res = await deleteUser(id);
            if (res.success) {
                fetchUsers(true);
            } else {
                alert(res.error);
            }
        }
    };

    const handleDeleteClick = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) handleDelete(id);
    }, [fetchUsers]);

    const openCreateModal = () => {
        setEditingUser(null);
        setSelectedRole('SALESPERSON');
        setSelectedPermissions(getDefaultPermissions('SALESPERSON'));
        setUseCustomPermissions(false);
        setError('');
        setIsModalOpen(true);
    };

    const openEditModal = (user: User) => {
        setEditingUser(user);
        setSelectedRole(user.role);
        setSelectedPermissions(user.permissions.length > 0 ? user.permissions : getDefaultPermissions(user.role));
        setUseCustomPermissions(user.permissions.length > 0);
        setError('');
        setIsModalOpen(true);
    };

    const handleEditClick = useCallback((e: React.MouseEvent<HTMLButtonElement>) => {
        const id = e.currentTarget.dataset.id;
        if (id) {
            const found = users.find(u => u.id === id);
            if (found) openEditModal(found);
        }
    }, [users]);

    const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        setError('');
        const formData = new FormData(e.currentTarget);

        // Add permissions to form data
        formData.set('permissions', JSON.stringify(useCustomPermissions ? selectedPermissions : []));

        if (editingUser) {
            const res = await updateUser(editingUser.id, formData);
            if (res.success) {
                setIsModalOpen(false);
                fetchUsers();
            } else {
                setError(res.error || 'Failed to update user');
            }
        } else {
            const res = await createUser(formData);
            if (res.success) {
                setIsModalOpen(false);
                fetchUsers();
            } else {
                setError(res.error || 'Failed to create user');
            }
        }
    };

    const togglePermission = (key: string) => {
        setSelectedPermissions(prev =>
            prev.includes(key)
                ? prev.filter(p => p !== key)
                : [...prev, key]
        );
    };

    const handleRoleChange = useCallback((e: React.ChangeEvent<HTMLSelectElement>) => setSelectedRole(e.target.value), []);
    const handleCustomPermissionsChange = useCallback((e: React.ChangeEvent<HTMLInputElement>) => setUseCustomPermissions(e.target.checked), []);
    const handleTogglePermissionClick = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
        const key = e.target.dataset.key;
        if (key) togglePermission(key);
    }, []);
    const handleCloseModalClick = useCallback(() => setIsModalOpen(false), []);

    return (
        <div className="space-y-6">
            <div className="flex justify-between items-center">
                <div>
                    <h1 className="text-2xl font-bold">Team Management</h1>
                    <p className="text-muted-foreground">Manage employees, salespersons, and accountants.</p>
                </div>
                <button
                    onClick={openCreateModal}
                    className="flex items-center gap-2 bg-primary text-primary-foreground px-4 py-2 rounded-lg hover:opacity-90 transition-opacity"
                >
                    <UserPlus size={20} />
                    Add Member
                </button>
            </div>

            {/* Role Legend */}
            <div className="flex flex-wrap gap-2">
                {Object.entries(ROLE_COLORS).map(([role, color]) => (
                    <span key={role} className={`text-xs px-2 py-1 rounded-full border ${color}`}>
                        {role}
                    </span>
                ))}
            </div>

            <div className="bg-card rounded-xl border border-border overflow-hidden">
                <table className="w-full text-left border-collapse">
                    <thead className="bg-secondary/50">
                        <tr>
                            <th className="px-6 py-4 font-semibold text-sm">Employee</th>
                            <th className="px-6 py-4 font-semibold text-sm">Contact</th>
                            <th className="px-6 py-4 font-semibold text-sm">Role</th>
                            <th className="px-6 py-4 font-semibold text-sm">Joined</th>
                            <th className="px-6 py-4 font-semibold text-sm text-right">Actions</th>
                        </tr>
                    </thead>
                    <tbody className="divide-y divide-border">
                        {isLoading ? (
                            <tr>
                                <td colSpan={5} className="px-6 py-8 text-center text-muted-foreground">Loading...</td>
                            </tr>
                        ) : users.map((user) => (
                            <tr key={user.id} className="hover:bg-secondary/20 transition-colors">
                                <td className="px-6 py-4">
                                    <div className="flex items-center gap-3">
                                        <div className={`w-10 h-10 rounded-full flex items-center justify-center text-white font-bold ${user.role === 'ROOT' ? 'bg-purple-500' :
                                            user.role === 'ADMIN' ? 'bg-blue-500' :
                                                user.role === 'ACCOUNTANT' ? 'bg-green-500' :
                                                    user.role === 'SALESPERSON' ? 'bg-orange-500' :
                                                        'bg-gray-500'
                                            }`}>
                                            {(user.name || user.username)[0].toUpperCase()}
                                        </div>
                                        <div>
                                            <div className="font-medium">{user.name || 'Anonymous'}</div>
                                            <div className="text-xs text-muted-foreground">@{user.username}</div>
                                        </div>
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <div className="space-y-1">
                                        {user.phone && (
                                            <div className="flex items-center gap-1 text-xs text-muted-foreground">
                                                <Phone size={12} /> {user.phone}
                                            </div>
                                        )}
                                        {user.address && (
                                            <div className="flex items-center gap-1 text-xs text-muted-foreground">
                                                <MapPin size={12} /> {user.address}
                                            </div>
                                        )}
                                        {!user.phone && !user.address && (
                                            <span className="text-xs text-muted-foreground">-</span>
                                        )}
                                    </div>
                                </td>
                                <td className="px-6 py-4">
                                    <span className={`inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-full text-xs font-medium border ${ROLE_COLORS[user.role] || ROLE_COLORS.READ_ONLY}`}>
                                        <Shield size={12} />
                                        {user.role}
                                    </span>
                                </td>
                                <td className="px-6 py-4 text-sm text-muted-foreground">
                                    {new Date(user.createdAt).toLocaleDateString()}
                                </td>
                                <td className="px-6 py-4 text-right">
                                    <div className="flex items-center justify-end gap-2">
                                        <Link prefetch={false}
                                            href={`/logs?user=${user.id}`}
                                            className="p-2 text-muted-foreground hover:text-blue-500 transition-colors"
                                            title="View Activity"
                                        >
                                            <Eye size={18} />
                                        </Link>
                                        {user.role !== 'ROOT' && (
                                            <>
                                                <button
                                                    data-id={user.id}
                                                    onClick={handleEditClick}
                                                    className="p-2 text-muted-foreground hover:text-primary transition-colors"
                                                    title="Edit"
                                                >
                                                    <Settings size={18} />
                                                </button>
                                                <button
                                                    data-id={user.id}
                                                    onClick={handleDeleteClick}
                                                    className="p-2 text-muted-foreground hover:text-red-500 transition-colors"
                                                    title="Delete"
                                                >
                                                    <Trash2 size={18} />
                                                </button>
                                            </>
                                        )}
                                    </div>
                                </td>
                            </tr>
                        ))}
                    </tbody>
                </table>
            </div>

            {/* Create/Edit User Modal */}
            {isModalOpen && (
                <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50">
                    <div className="bg-card w-full max-w-lg max-h-[90vh] overflow-y-auto p-6 rounded-2xl shadow-xl border border-border">
                        <h2 className="text-xl font-bold mb-4">
                            {editingUser ? 'Edit Team Member' : 'Add Team Member'}
                        </h2>
                        {error && (
                            <div className="bg-red-50 text-red-600 p-3 rounded-lg mb-4 text-sm">
                                {error}
                            </div>
                        )}
                        <form onSubmit={handleSubmit} className="space-y-4">
                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Full Name</label>
                                    <input
                                        name="name"
                                        type="text"
                                        defaultValue={editingUser?.name || ''}
                                        className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                        required
                                        placeholder="John Doe"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Username</label>
                                    <input
                                        name="username"
                                        type="text"
                                        defaultValue={editingUser?.username || ''}
                                        className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                        required
                                        placeholder="johndoe"
                                        disabled={!!editingUser}
                                    />
                                </div>
                            </div>

                            {!editingUser && (
                                <>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium">Email Address</label>
                                        <input name="email" type="email" className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20" required placeholder="john@coffee.com" />
                                    </div>
                                    <div className="space-y-2">
                                        <label className="text-sm font-medium">Password</label>
                                        <input name="password" type="password" className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20" required placeholder="••••••••" minLength={6} />
                                    </div>
                                </>
                            )}

                            <div className="grid grid-cols-2 gap-4">
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Phone</label>
                                    <input
                                        name="phone"
                                        type="tel"
                                        defaultValue={editingUser?.phone || ''}
                                        className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                        placeholder="01xxxxxxxxx"
                                    />
                                </div>
                                <div className="space-y-2">
                                    <label className="text-sm font-medium">Address</label>
                                    <input
                                        name="address"
                                        type="text"
                                        defaultValue={editingUser?.address || ''}
                                        className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                        placeholder="Cairo, Egypt"
                                    />
                                </div>
                            </div>

                            <div className="space-y-2">
                                <label className="text-sm font-medium">Role</label>
                                <select
                                    name="role"
                                    value={selectedRole}
                                    onChange={handleRoleChange}
                                    className="w-full bg-secondary/50 border border-border rounded-lg p-2.5 outline-none focus:ring-2 ring-primary/20"
                                >
                                    <option value="SALESPERSON">Salesperson (Carrier)</option>
                                    <option value="ACCOUNTANT">Accountant</option>
                                    <option value="ADMIN">Admin</option>
                                    <option value="READ_ONLY">Read Only</option>
                                </select>
                                <p className="text-[10px] text-muted-foreground italic">ROOT role can only be assigned via database.</p>
                            </div>

                            {/* Permissions Section */}
                            <div className="space-y-3 p-4 bg-secondary/30 rounded-xl border border-border">
                                <div className="flex items-center justify-between">
                                    <label className="text-sm font-bold">Page Permissions</label>
                                    <label className="flex items-center gap-2 text-xs">
                                        <input
                                            type="checkbox"
                                            checked={useCustomPermissions}
                                            onChange={handleCustomPermissionsChange}
                                            className="rounded"
                                        />
                                        Custom permissions
                                    </label>
                                </div>
                                <div className="grid grid-cols-2 gap-2">
                                    {ALL_PERMISSIONS.map(perm => (
                                        <label
                                            key={perm.key}
                                            className={`flex items-center gap-2 text-sm p-2 rounded-lg cursor-pointer transition-colors ${selectedPermissions.includes(perm.key)
                                                ? 'bg-primary/10 text-primary'
                                                : 'bg-secondary/50 text-muted-foreground'
                                                } ${!useCustomPermissions ? 'opacity-60' : ''}`}
                                        >
                                            <input
                                                type="checkbox"
                                                checked={selectedPermissions.includes(perm.key)}
                                                data-key={perm.key}
                                                onChange={handleTogglePermissionClick}
                                                disabled={!useCustomPermissions}
                                                className="rounded"
                                            />
                                            {perm.label}
                                        </label>
                                    ))}
                                </div>
                                {!useCustomPermissions && (
                                    <p className="text-[10px] text-muted-foreground">Using default permissions for {selectedRole} role.</p>
                                )}
                            </div>

                            <div className="flex gap-3 pt-4">
                                <button type="button" onClick={handleCloseModalClick} className="flex-1 px-4 py-2.5 rounded-lg border border-border hover:bg-secondary transition-colors">Cancel</button>
                                <button type="submit" className="flex-1 bg-primary text-primary-foreground px-4 py-2.5 rounded-lg hover:opacity-90 transition-opacity">
                                    {editingUser ? 'Update' : 'Create'} User
                                </button>
                            </div>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}

'use server';

import getPrisma from '@/lib/prisma';
import { revalidatePath } from 'next/cache';

export async function getInventory() {
    const prisma = getPrisma();

    const inventory = await prisma.inventory.findMany({
        include: {
            product: {
                include: {
                    category: true
                }
            },
            location: true
        },
        orderBy: {
            product: { name: 'asc' }
        }
    });

    return inventory.map(item => ({
        ...item,
        product: {
            ...item.product,
            costPrice: Number(item.product.costPrice),
            baseSellingPrice: Number(item.product.baseSellingPrice)
        }
    }));
}

export async function getCategories() {
    const prisma = getPrisma();
    return prisma.category.findMany({
        orderBy: { name: 'asc' },
        include: {
            _count: { select: { products: true } }
        }
    });
}

export async function createCategory(name: string) {
    const prisma = getPrisma();
    try {
        const category = await prisma.category.create({
            data: { name }
        });

        try {
            const { logActivity } = await import('./audit');
            await logActivity('CREATE_CATEGORY', `Created category "${name}"`);
        } catch (e) {
            console.error('Audit log failed', e);
        }

        revalidatePath('/products');
        return { success: true, category };
    } catch (error: unknown) {
        if (typeof error === 'object' && error !== null && 'code' in error && (error as any).code === 'P2002') {
            return { success: false, error: 'Category name already exists.' };
        }
        return { success: false, error: 'Failed to create category.' };
    }
}

export async function deleteCategory(id: string) {
    const prisma = getPrisma();
    try {
        // Check if category has products
        const count = await prisma.product.count({ where: { categoryId: id } });
        if (count > 0) {
            return { success: false, error: `Cannot delete: ${count} products use this category.` };
        }
        await prisma.category.delete({ where: { id } });

        try {
            const { logActivity } = await import('./audit');
            await logActivity('DELETE_CATEGORY', `Deleted category ID: ${id}`);
        } catch (e) {
            console.error('Audit log failed', e);
        }

        revalidatePath('/products');
        return { success: true };
    } catch {
        return { success: false, error: 'Failed to delete category.' };
    }
}

export async function createProduct(data: {
    name: string;
    sku: string;
    categoryId: string;
    costPrice: number;
    baseSellingPrice: number;
    retailPrice?: number;
    lowestRetailPrice?: number;
    wholesalePrice?: number;
    lowestWholesalePrice?: number;
    unit?: string;
    image?: string;
    initialQuantity?: number;
}) {
    const prisma = getPrisma();

    try {
        // Check for duplicate SKU
        const existingSku = await prisma.product.findFirst({
            where: { sku: data.sku }
        });
        if (existingSku) {
            return { success: false, error: `SKU "${data.sku}" already exists. Please use a unique SKU.` };
        }

        const product = await prisma.$transaction(async (tx) => {
            // 1. Create Product
            const newProduct = await tx.product.create({
                data: {
                    name: data.name,
                    sku: data.sku,
                    categoryId: data.categoryId,
                    costPrice: data.costPrice,
                    baseSellingPrice: data.baseSellingPrice,
                    retailPrice: data.retailPrice || 0,
                    lowestRetailPrice: data.lowestRetailPrice || 0,
                    wholesalePrice: data.wholesalePrice || 0,
                    lowestWholesalePrice: data.lowestWholesalePrice || 0,
                    unit: data.unit || 'piece',
                    image: data.image
                }
            });

            // 2. Self-healing Location (Ensure at least one location exists)
            let location = await tx.location.findFirst();
            if (!location) {
                location = await tx.location.create({
                    data: { name: "Main Warehouse", type: "WAREHOUSE" }
                });
            }

            // 3. Create Initial Inventory if provided
            if (data.initialQuantity !== undefined && data.initialQuantity > 0) {
                await tx.inventory.create({
                    data: {
                        productId: newProduct.id,
                        locationId: location.id,
                        quantity: data.initialQuantity
                    }
                });

                // [NEW] Create Transaction for Opening Stock
                await tx.transaction.create({
                    data: {
                        type: 'IN',
                        toLocationId: location.id,
                        items: {
                            create: [{
                                productId: newProduct.id,
                                quantity: data.initialQuantity
                            }]
                        }
                    }
                });
            }

            return newProduct;
        });

        // 4. Audit Log
        try {
            const { logActivity } = await import('./audit');
            await logActivity('CREATE_PRODUCT', `Created product "${data.name}" (${data.sku})`);
        } catch (e) {
            console.error('Audit log failed', e);
        }

        revalidatePath('/inventory');
        revalidatePath('/sales');
        revalidatePath('/dashboard');

        return {
            success: true,
            product: {
                ...product,
                costPrice: Number(product.costPrice),
                baseSellingPrice: Number(product.baseSellingPrice)
            }
        };
    } catch (error: unknown) {
        if (typeof error === 'object' && error !== null && 'code' in error && (error as any).code === 'P2002' && (error as any).meta?.target?.includes('sku')) {
            return {
                success: false,
                error: 'SKU already exists. Please use a unique code.'
            };
        }
        return {
            success: false,
            error: 'Failed to create product. Please try again.'
        };
    }
}

export async function getUnifiedProducts() {
    const prisma = getPrisma();

    const products = await prisma.product.findMany({
        include: {
            category: true,
            inventoryItems: {
                include: { location: true }
            }
        },
        orderBy: { name: 'asc' }
    });

    // Compute grand total stock across all products
    const grandTotal = products.reduce((sum, p) =>
        sum + p.inventoryItems.reduce((s, inv) => s + inv.quantity, 0), 0
    );

    return products.map(p => {
        const totalStock = p.inventoryItems.reduce((s, inv) => s + inv.quantity, 0);
        const percentOfTotal = grandTotal > 0 ? Number(((totalStock / grandTotal) * 100).toFixed(1)) : 0;

        return {
            id: p.id,
            name: p.name,
            sku: p.sku,
            unit: p.unit,
            categoryId: p.categoryId,
            categoryName: p.category?.name || 'Uncategorized',
            costPrice: Number(p.costPrice),
            baseSellingPrice: Number(p.baseSellingPrice),
            retailPrice: Number(p.retailPrice),
            lowestRetailPrice: Number(p.lowestRetailPrice),
            wholesalePrice: Number(p.wholesalePrice),
            lowestWholesalePrice: Number(p.lowestWholesalePrice),
            image: p.image,
            totalStock,
            percentOfTotal,
            locationBreakdown: p.inventoryItems.map(inv => ({
                locationId: inv.locationId,
                locationName: inv.location.name,
                locationType: inv.location.type,
                quantity: inv.quantity
            }))
        };
    });
}

export async function updateProduct(id: string, data: {
    name: string;
    sku: string;
    categoryId: string;
    costPrice: number;
    baseSellingPrice: number;
    retailPrice?: number;
    lowestRetailPrice?: number;
    wholesalePrice?: number;
    lowestWholesalePrice?: number;
    unit?: string;
    image?: string;
}) {
    const prisma = getPrisma();

    try {
        const product = await prisma.product.update({
            where: { id },
            data: {
                name: data.name,
                sku: data.sku,
                categoryId: data.categoryId,
                costPrice: data.costPrice,
                baseSellingPrice: data.baseSellingPrice,
                retailPrice: data.retailPrice || 0,
                lowestRetailPrice: data.lowestRetailPrice || 0,
                wholesalePrice: data.wholesalePrice || 0,
                lowestWholesalePrice: data.lowestWholesalePrice || 0,
                unit: data.unit || 'piece',
                image: data.image
            }
        });

        // Audit Log
        try {
            const { logActivity } = await import('./audit');
            await logActivity('UPDATE_PRODUCT', `Updated product "${data.name}" (${data.sku})`);
        } catch (e) {
            console.error('Audit log failed', e);
        }

        revalidatePath('/inventory');
        revalidatePath('/sales');
        revalidatePath('/dashboard');

        return {
            success: true,
            product: {
                ...product,
                costPrice: Number(product.costPrice),
                baseSellingPrice: Number(product.baseSellingPrice)
            }
        };
    } catch (error: unknown) {
        if (typeof error === 'object' && error !== null && 'code' in error && (error as any).code === 'P2002' && (error as any).meta?.target?.includes('sku')) {
            return {
                success: false,
                error: 'SKU already exists. Please use a unique code.'
            };
        }
        return {
            success: false,
            error: 'Failed to update product. Please try again.'
        };
    }
}
